import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"简介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/introduction.md","filePath":"zh-CN/guide/introduction.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to “简介”">​</a></h1><h2 id="关于-sudoku" tabindex="-1">关于 Sudoku <a class="header-anchor" href="#关于-sudoku" aria-label="Permalink to “关于 Sudoku”">​</a></h2><p><strong>Sudoku —— 经典数字谜题，匠心打造。</strong></p><p><img src="/screenshot-ipad-main.png" alt="在 iPad 上运行的 Sudoku"></p><p>重新发现你钟爱的经典逻辑谜题，为现代设备精心打磨：顺滑的操作、精美的主题，还有玩不完的题目。无论你是初次接触，还是经验丰富的老手，这都是你一直在等待的数独体验。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><h3 id="🔢-纯正玩法" tabindex="-1">🔢 <strong>纯正玩法</strong> <a class="header-anchor" href="#🔢-纯正玩法" aria-label="Permalink to “🔢 纯正玩法”">​</a></h3><p>忠于经典规则——填满 9×9 的网格，使每一行、每一列和每个 3×3 宫都恰好包含 1 到 9 各一次。点按填入数字，用铅笔笔记标记候选数，让逻辑带你走向答案。</p><h3 id="🎯-5-种难度" tabindex="-1">🎯 <strong>5 种难度</strong> <a class="header-anchor" href="#🎯-5-种难度" aria-label="Permalink to “🎯 5 种难度”">​</a></h3><p>五种经过精心校准的难度，已知格数量各不相同：</p><table tabindex="0"><thead><tr><th>级别</th><th>已知格</th><th>说明</th></tr></thead><tbody><tr><td>简单</td><td>45</td><td>适合新手和快速来一局</td></tr><tr><td>中等</td><td>36</td><td>为休闲玩家准备的均衡挑战</td></tr><tr><td>困难</td><td>31</td><td>需要运用逻辑推理技巧</td></tr><tr><td>专家</td><td>27</td><td>给想真正接受考验的老手</td></tr><tr><td>大师</td><td>24</td><td>终极挑战——只留给最勇敢的人</td></tr></tbody></table><p>每一道题目都是独立生成的——没有两局会完全相同。</p><h3 id="📱-通用-app" tabindex="-1">📱 <strong>通用 App</strong> <a class="header-anchor" href="#📱-通用-app" aria-label="Permalink to “📱 通用 App”">​</a></h3><p>一次购买即可在 iPhone、iPad 和 Mac 上使用。每个平台都有原生控件——iOS 上支持触摸手势，Mac 上支持鼠标和键盘。你的进度会通过 iCloud 在所有设备间同步。</p><p><img src="/screenshot-iphone-main.png" alt="iPhone 上的 Sudoku"></p><p><img src="/screenshot-mac-difficulty.png" alt="Mac 上的 Sudoku"></p><h3 id="💡-提示与笔记" tabindex="-1">💡 <strong>提示与笔记</strong> <a class="header-anchor" href="#💡-提示与笔记" aria-label="Permalink to “💡 提示与笔记”">​</a></h3><ul><li><strong>提示</strong>：卡住了？获取一个提示，它会揭示一个正确的格子，而不会提前泄露整道题。</li><li><strong>铅笔笔记</strong>：开启铅笔模式，在空格里记下候选数字。当你填入一个数字时，同行、同列、同宫中的相同候选标记会自动清除。</li><li><strong>错误检查</strong>：可选择高亮显示填错的数字，让你从错误中学习。</li><li><strong>撤销</strong>：支持完整撤销——任何时候都能悔棋。</li></ul><h3 id="🏆-每日挑战" tabindex="-1">🏆 <strong>每日挑战</strong> <a class="header-anchor" href="#🏆-每日挑战" aria-label="Permalink to “🏆 每日挑战”">​</a></h3><p>每天一道全新的题目，难度为大师级。积累连续天数，并在统计的日历视图中查看每日进度。</p><h3 id="📊-统计" tabindex="-1">📊 <strong>统计</strong> <a class="header-anchor" href="#📊-统计" aria-label="Permalink to “📊 统计”">​</a></h3><p>追踪你的表现：总局数、胜率、当前连续天数、最长连续天数，以及按难度细分的最佳成绩和平均成绩。数据通过 iCloud 同步。</p><h3 id="🎨-8-种精美主题" tabindex="-1">🎨 <strong>8 种精美主题</strong> <a class="header-anchor" href="#🎨-8-种精美主题" aria-label="Permalink to “🎨 8 种精美主题”">​</a></h3><p>用八种手工调配的配色主题个性化你的棋盘：经典、午夜、纸张、森林、海洋、日落、薰衣草和玫瑰。每种主题都带来独特的视觉体验，同时保持出色的可读性。</p><h3 id="☁️-icloud-同步" tabindex="-1">☁️ <strong>iCloud 同步</strong> <a class="header-anchor" href="#☁️-icloud-同步" aria-label="Permalink to “☁️ iCloud 同步”">​</a></h3><p>你的设置、统计数据、游戏存档和每日挑战进度会通过 CloudKit 自动同步到你的所有 Apple 设备。可以在 iPhone 上开局，在 Mac 上继续。</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>用你的最佳完成时间在排行榜上一较高下，并赢取成就：首次通关、简单通关、中等通关、困难通关、专家通关、大师通关，以及完美通关（不使用提示且不出现错误）。</p><h3 id="🔇-界面简洁-无广告" tabindex="-1">🔇 <strong>界面简洁，无广告</strong> <a class="header-anchor" href="#🔇-界面简洁-无广告" aria-label="Permalink to “🔇 界面简洁，无广告”">​</a></h3><p>没有打断，没有弹窗，没有广告，也没有 App 内购买。只有纯粹、专注的解谜乐趣。</p><h3 id="🌍-25-种语言" tabindex="-1">🌍 <strong>25 种语言</strong> <a class="header-anchor" href="#🌍-25-种语言" aria-label="Permalink to “🌍 25 种语言”">​</a></h3><p>在设置中即可在运行时切换语言，无需重启应用。支持英语、简体中文、繁体中文、日语、韩语、法语、德语、西班牙语、意大利语、俄语、葡萄牙语、荷兰语、越南语、泰语、印地语、土耳其语、希腊语、芬兰语、挪威语、丹麦语、匈牙利语、印尼语、马来语、乌克兰语，以及德语（瑞士）。</p><h3 id="🔊-音效" tabindex="-1">🔊 <strong>音效</strong> <a class="header-anchor" href="#🔊-音效" aria-label="Permalink to “🔊 音效”">​</a></h3><p>为落子、提示、错误和胜利准备了细腻的音效——可在设置中随时开关。</p><h3 id="🖨️-打印题目" tabindex="-1">🖨️ <strong>打印题目</strong> <a class="header-anchor" href="#🖨️-打印题目" aria-label="Permalink to “🖨️ 打印题目”">​</a></h3><p>在 Mac 版应用中直接打印题目，可选择难度，还能附上答案。非常适合用纸笔线下解题。</p><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to “系统要求”">​</a></h2><ul><li><strong>iPhone/iPad</strong>：iOS/iPadOS 16.0 或更高版本</li><li><strong>Mac</strong>：macOS 15.0（Sequoia）或更高版本（Apple Silicon）</li><li><strong>存储空间</strong>：约 50 MB</li></ul><h2 id="隐私" tabindex="-1">隐私 <a class="header-anchor" href="#隐私" aria-label="Permalink to “隐私”">​</a></h2><p>Sudoku 的核心玩法以离线为先。所有游戏数据都存储在本地，并且只会同步到你个人的 iCloud 账户。没有广告，没有数据分析，也没有第三方追踪。唯一涉及网络的功能是 iCloud 同步、Game Center，以及设置中可选的“更多 App”板块。</p><p>详情请参阅<a href="/zh-CN/guide/privacy.html">隐私政策</a>。</p><h2 id="开始使用" tabindex="-1">开始使用 <a class="header-anchor" href="#开始使用" aria-label="Permalink to “开始使用”">​</a></h2><p>如果你是数独新手，请先阅读<a href="/zh-CN/guide/installation.html">安装指南</a>，把应用装到你的设备上。</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};